property bool supportsInactiveDeactivated: hasElementPrefix("deactivated-inactive")
// VeltOS: square hover/pressed pictures for maximised windows, if the theme has them
readonly property string maximizedSuffix: decoration.client.maximized && hasElementPrefix("hover-maximized") ? "-maximized" : ""
// VeltOS: white glyphs on the Office apps' coloured title bars (see veltosTint in aurorae.qml), if the theme has them
readonly property bool veltosTinted: String(auroraeTheme.decorationPath).indexOf("Dark") < 0 && ["VeltOS Office Writer", "VeltOS Office Calc", "VeltOS Office Impress"].some(name => String(decoration.client.caption).endsWith(name))
readonly property string tintSuffix: veltosTinted && hasElementPrefix("active-ondark") ? "-ondark" : ""

property alias supportsMask: backgroundSvg.supportsMask
// VeltOS: the Office apps' windows carry their app's colour in the title bar (Word blue, Excel green,
// PowerPoint orange), as Microsoft 365's do on Windows 11; on the light frame only (the dark frame stays
// dark, like Office's Black theme). The windows are told by their caption, "... — VeltOS Office Writer"
// (the product name veltos-office gives LibreOffice); KDecoration3 exposes no window class to QML.
readonly property color veltosTint: {
    if (String(auroraeTheme.decorationPath).indexOf("Dark") >= 0)
        return "transparent";
    const caption = String(decoration.client.caption);
    if (caption.endsWith("VeltOS Office Writer"))
        return "#185ABD";
    if (caption.endsWith("VeltOS Office Calc"))
        return "#107C41";
    if (caption.endsWith("VeltOS Office Impress"))
        return "#C43E1C";
    return "transparent";
}
readonly property bool veltosTinted: veltosTint.a > 0

Rectangle {
    // VeltOS: app-coloured title bar (veltosTint); inactive windows a lighter shade
    visible: root.veltosTinted
    x: decoration.client.maximized ? 0 : root.padding.left
