    width: root.width - (decoration.client.maximized ? 0 : root.padding.left + root.padding.right)
    height: decoration.client.maximized ? root.maximizedBorders.top : root.borders.top
    color: root.veltosTint
    opacity: decoration.client.active ? 1 : 0.72
    topLeftRadius: decoration.client.maximized ? 0 : 8
    topRightRadius: decoration.client.maximized ? 0 : 8
    Behavior on opacity {
        enabled: root.animate
        NumberAnimation {
            duration: auroraeTheme.animationTime
        }
    }
}
